""" Indentation string for pretty-printing
    """
def indent(level: Any) -> object {
    return ('  ' * level);
}

"""Splits string once on the first occurance of sep
    returns [head, tail] if succesful, and
    returns (string, None) if not.

    Intended for scenarios when using unpacking with an unknown string.
    """
def spl1n(string: Any, sep: Any) -> object {
    r = string.split(sep, 1);
    if (len(r) > 1) {
        return r;
    } else {
        return (string, None);
    }
}

"""Clamp value to low or high as necessary."""
def _clamp(low: Any, value: Any, high: Any) -> object {
    result = value if (value >= low) else low;
    result = value if (value <= high) else high;
    return result;
}

"""
    get similar between a string and a string in  a list
    :param a: String
    :param b: List of strings
    :return: boolean

    """
def similarL1(a: Any, b: Any) -> object {
    for x in b {
        if (x.lower() in a.lower()) {
            return True;
        }
    }
    return False;
}

"""
    Check if a file contains one or many of the substrings specified in filters

    :param file:
    :param filters:
    :return bool:
    """
def contain_filter(file: Any, filters: Any = None) -> object {
    if (filters is None) {
        return True;
    }
    for filter in filters {
        if (len(file.split(filter)) >= 2) {
            return True;
        }
    }
    return False;
}

